import type { MigrationMeta } from 'drizzle-orm/migrator';
import type { SQLiteAsyncDialect, SQLiteSession } from 'drizzle-orm/sqlite-core';
import type { AppDatabase } from './database';

/** The shape of src/db/migrations/migrations.js, generated by drizzle-kit (`driver: 'expo'`). */
export type MigrationBundle = {
  journal: { entries: { idx: number; when: number; tag: string; breakpoints: boolean }[] };
  migrations: Record<string, string>;
};

const STATEMENT_BREAKPOINT = '--> statement-breakpoint';

/** Converts the bundled journal + SQL into Drizzle's migration list, in journal order. */
export function toMigrationMeta(bundle: MigrationBundle): MigrationMeta[] {
  return bundle.journal.entries.map(entry => {
    const sql = bundle.migrations[`m${String(entry.idx).padStart(4, '0')}`];
    if (sql === undefined) {
      throw new Error(`Missing migration SQL for ${entry.tag}`);
    }
    return {
      sql: sql.split(STATEMENT_BREAKPOINT),
      bps: entry.breakpoints,
      folderMillis: entry.when,
      hash: '',
    };
  });
}

// `dialect` and `session` exist on every Drizzle database at runtime but are marked
// internal in the typings; this is exactly what drizzle's own op-sqlite migrator calls.
type MigratableDatabase = {
  dialect: SQLiteAsyncDialect;
  session: SQLiteSession<'async', unknown, Record<string, unknown>, never>;
};

/**
 * Applies pending migrations in a transaction. Already applied ones (tracked in
 * __drizzle_migrations) are skipped, so this is safe to run on every start.
 */
export async function migrateDatabase(db: AppDatabase, bundle: MigrationBundle): Promise<void> {
  const { dialect, session } = db as unknown as MigratableDatabase;
  await dialect.migrate(toMigrationMeta(bundle), session);
}
